-- ---------------------------------------------------------------------------
-- Hand-written (Prisma cannot express these)
-- ---------------------------------------------------------------------------

-- At most one open QR session per table: every phone that scans joins the same visit.
CREATE UNIQUE INDEX "qr_sessions_one_open_per_table"
  ON "qr_sessions" ("table_id") WHERE "status" = 'OPEN';

-- De-duplicate manager alerts: one open no-captain alert per table, one escalation per round.
CREATE UNIQUE INDEX "qr_alerts_one_open_no_captain_per_table"
  ON "qr_alerts" ("table_id") WHERE "kind" = 'NO_CAPTAIN' AND "status" = 'OPEN';
CREATE UNIQUE INDEX "qr_alerts_one_open_escalation_per_round"
  ON "qr_alerts" ("round_id") WHERE "kind" = 'ESCALATION' AND "status" = 'OPEN';

-- Sanity checks the API also enforces.
ALTER TABLE "restaurants" ADD CONSTRAINT "restaurants_qr_escalation_minutes_range"
  CHECK ("qr_escalation_minutes" BETWEEN 1 AND 15);
ALTER TABLE "qr_cart_items" ADD CONSTRAINT "qr_cart_items_quantity_positive" CHECK ("quantity" > 0);
ALTER TABLE "qr_round_items" ADD CONSTRAINT "qr_round_items_quantity_range"
  CHECK ("quantity" >= 0 AND "requested_quantity" > 0);

-- Restaurants created by the dev seed before it was fixed have an OWNER role without the bypass
-- flag (signup always sets it), so their owner would be locked out of every new permission. Mark
-- it as the Owner, as REST-79 intended, where the restaurant has no owner role yet. Idempotent.
UPDATE "roles" r SET "is_owner" = true
  WHERE r."name" = 'OWNER' AND r."is_system" AND NOT r."is_owner"
    AND NOT EXISTS (
      SELECT 1 FROM "roles" o WHERE o."restaurant_id" = r."restaurant_id" AND o."is_owner"
    );
DELETE FROM "role_permissions" WHERE "role_id" IN (SELECT "id" FROM "roles" WHERE "is_owner");

-- Seed the new permission keys onto existing default roles (matches ROLE_PERMISSIONS in
-- @rms/permissions). The Owner role bypasses checks and holds no rows. Idempotent.
INSERT INTO "role_permissions" ("role_id", "permission_key")
  SELECT r."id", d.permission
  FROM "roles" r
  JOIN (VALUES
    ('MANAGER', 'qr-order:read'),
    ('MANAGER', 'qr-order:approve'),
    ('MANAGER', 'qr-order:manage'),
    ('MANAGER', 'qr-settings:write'),
    ('CAPTAIN', 'qr-order:read'),
    ('CAPTAIN', 'qr-order:approve')
  ) AS d(role_name, permission) ON d.role_name = r."name"
  WHERE r."is_system" AND NOT r."is_owner"
ON CONFLICT DO NOTHING;
